// Alegra devuelve máximo 30 cotizaciones por llamada, así que el nodo anterior
// hace varias llamadas y entrega una página por cada una.
// Aquí las abrimos para quedar con una cotización por item.

const cotizaciones = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    cotizaciones.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    cotizaciones.push(...cuerpo.data);
  } else {
    cotizaciones.push(cuerpo);
  }
}

return cotizaciones.map((cotizacion) => ({ json: cotizacion }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const DIAS_PARA_ENFRIARSE = 15;   // desde cuántos días sin respuesta te avisa
const MONTO_MINIMO = 0;           // ignora las cotizaciones por debajo de este monto
const MONEDA = 'COP';
// ──────────────────────────────────────────────────────────────────────

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const frias = [];

for (const item of items) {
  const c = item.json;

  // Si Alegra nos dijo qué facturas salieron de esta cotización y hay al menos
  // una, ya se convirtió y no hay nada que perseguir.
  if (Array.isArray(c.invoices) && c.invoices.length > 0) continue;

  if (!c.date) continue;
  // La fecha viene como '2026-08-01'. Sin la hora, JavaScript la lee en UTC y
  // en Colombia queda corrida un día.
  const emitida = new Date(String(c.date).slice(0, 10) + 'T00:00:00');
  if (isNaN(emitida.getTime())) continue;

  const dias = Math.floor((hoy - emitida) / 86400000);
  if (dias < DIAS_PARA_ENFRIARSE) continue;

  const total = Number(c.total ?? 0);
  if (total < MONTO_MINIMO) continue;

  frias.push({
    id: String(c.id ?? ''),
    numero:
      (c.numberTemplate && c.numberTemplate.fullNumber) ||
      String(c.number ?? c.id ?? 'sin número'),
    cliente: (c.client && c.client.name) || 'Cliente sin nombre',
    fecha: c.date,
    dias,
    total,
    totalTexto: plata(total),
  });
}

// Si no hay ninguna fría, no devolvemos nada y el correo no sale.
if (frias.length === 0) return [];

// La plata más grande arriba: es la que más vale la pena perseguir.
frias.sort((a, b) => b.total - a.total);

const total = frias.reduce((s, f) => s + f.total, 0);

const filas = frias
  .map(
    (f) =>
      '<tr>' +
      '<td style="padding:4px 12px 4px 0">' + f.numero + '</td>' +
      '<td style="padding:4px 12px 4px 0">' + f.cliente + '</td>' +
      '<td style="padding:4px 12px 4px 0"><b>' + f.totalTexto + '</b></td>' +
      '<td style="padding:4px 0">hace ' + f.dias + ' días</td>' +
      '</tr>'
  )
  .join('');

const mensaje = [
  '<p>Tienes <b>' + frias.length + ' cotización(es)</b> que llevan más de ' +
    DIAS_PARA_ENFRIARSE + ' días sin convertirse en factura, ' +
    'por un total de <b>' + plata(total) + '</b>.</p>',
  '<table>' + filas + '</table>',
  '<p>Empieza por la de arriba: es la que más plata te representa.</p>',
  '<p style="color:#666;font-size:13px">Para convertir una en factura borrador, ' +
    'abre el formulario de este mismo flujo y escribe su número.</p>',
].join('\n');

return [
  {
    json: {
      asunto:
        frias.length === 1
          ? 'Una cotización se está enfriando: ' + frias[0].numero
          : frias.length + ' cotizaciones se están enfriando',
      mensaje,
      cantidad: frias.length,
      total,
      totalTexto: plata(total),
    },
  },
];

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const FORMA_DE_PAGO = 'CREDIT';   // CREDIT = le das plazo. CASH = paga de contado
const METODO_DE_PAGO = 'CASH';
const DIAS_PARA_PAGAR = 30;       // plazo de la factura que se crea
const MONEDA = 'COP';
// ──────────────────────────────────────────────────────────────────────

const numeroPedido = String(
  $('Convertir una cotización').first().json.numero ?? ''
).trim();

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const noSePudo = (motivo) => [
  { json: { ok: false, numero: numeroPedido, motivo, factura: null } },
];

// ── Juntar lo que devolvió Alegra ──
const encontradas = [];
for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    encontradas.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    encontradas.push(...cuerpo.data);
  } else if (cuerpo && cuerpo.id) {
    encontradas.push(cuerpo);
  }
}

if (encontradas.length === 0) {
  return noSePudo(
    'No encontré ninguna cotización con el número ' + numeroPedido +
    '. Revisa que esté escrito igual que en Alegra.'
  );
}

const c = encontradas[0];

const clienteId = c.client && c.client.id;
if (!clienteId) {
  return noSePudo(
    'La cotización ' + numeroPedido + ' no tiene un cliente asociado en Alegra.'
  );
}

// ── Pasar las líneas de la cotización a líneas de factura ──
// El precio puede venir como número o como objeto, según la cuenta.
const precioDe = (l) => {
  if (typeof l.price === 'number') return l.price;
  if (l.price && typeof l.price.price === 'number') return l.price.price;
  return Number(l.price ?? 0);
};

const lineas = (Array.isArray(c.items) ? c.items : [])
  .map((l) => {
    const linea = {
      id: String(l.id ?? (l.item && l.item.id) ?? ''),
      name: String(l.name ?? (l.item && l.item.name) ?? 'Ítem'),
      price: Number(precioDe(l)) || 0,
      quantity: Number(l.quantity ?? 1) || 1,
    };
    if (Number(l.discount ?? 0) > 0) linea.discount = Number(l.discount);
    if (l.tax && l.tax.id) linea.tax = { id: String(l.tax.id) };
    else if (Array.isArray(l.tax) && l.tax[0] && l.tax[0].id) {
      linea.tax = { id: String(l.tax[0].id) };
    }
    return linea;
  })
  .filter((l) => l.id && l.price > 0 && l.quantity > 0);

if (lineas.length === 0) {
  return noSePudo(
    'La cotización ' + numeroPedido + ' no tiene ítems que se puedan facturar.'
  );
}

// ── Armar la factura ──
const hoy = new Date();
const fecha = (d) =>
  d.getFullYear() +
  '-' + String(d.getMonth() + 1).padStart(2, '0') +
  '-' + String(d.getDate()).padStart(2, '0');

const vence = new Date(hoy);
vence.setDate(vence.getDate() + DIAS_PARA_PAGAR);

const numeroReal =
  (c.numberTemplate && c.numberTemplate.fullNumber) ||
  String(c.number ?? c.id);

const total = lineas.reduce((s, l) => s + l.price * l.quantity, 0);

return [
  {
    json: {
      ok: true,
      numero: numeroReal,
      cotizacionId: String(c.id),
      cliente: (c.client && c.client.name) || 'Cliente sin nombre',
      cantidadLineas: lineas.length,
      total,
      totalTexto: plata(total),
      // Este es el cuerpo exacto que se le manda a Alegra.
      // status draft = borrador. No se emite nada solo.
      factura: {
        client: { id: String(clienteId) },
        date: fecha(hoy),
        dueDate: fecha(vence),
        status: 'draft',
        paymentForm: FORMA_DE_PAGO,
        paymentMethod: METODO_DE_PAGO,
        items: lineas,
        anotation: 'Creada desde la cotización ' + numeroReal + '. Queda en borrador.',
      },
    },
  },
];

// Lo que este nodo devuelva es lo que ve la persona en la página del formulario.

const MONEDA = 'COP';
const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const d = (items[0] && items[0].json) || {};

// No se pudo armar la factura: el nodo anterior explicó por qué.
if (d.ok === false) {
  return [{ json: { resultado: 'No se pudo', mensaje: d.motivo } }];
}

// Alegra devolvió un error al crear.
if (d.error) {
  return [
    {
      json: {
        resultado: 'No se pudo',
        mensaje:
          'Alegra rechazó la factura. Abre la ejecución en n8n para ver el detalle.',
      },
    },
  ];
}

// El nodo que crea la factura está desactivado: esto fue una prueba en seco.
if (d.ok === true) {
  return [
    {
      json: {
        resultado: 'Prueba en seco',
        mensaje:
          'No se creó nada en Alegra porque el nodo "Crear la factura borrador" está desactivado. ' +
          'Si lo activas, la cotización ' + d.numero + ' de ' + d.cliente +
          ' se convertiría en una factura borrador de ' + d.totalTexto +
          ' con ' + d.cantidadLineas + ' línea(s).',
      },
    },
  ];
}

// Caso normal: Alegra devolvió la factura creada.
const numero =
  (d.numberTemplate && d.numberTemplate.fullNumber) || 'sin numerar';
const cliente = (d.client && d.client.name) || 'tu cliente';

return [
  {
    json: {
      resultado: 'Listo',
      mensaje:
        'La factura ' + numero + ' de ' + cliente + ' por ' +
        plata(Number(d.total ?? 0)) +
        ' quedó creada en Alegra como borrador. Revísala allá y emítela cuando quieras.',
    },
  },
];
